actions.script:
hasDrive = false
personalDriveId = null
driveList = []
recentList = []
if (checkOnly) {
    if (!ec.user.userId) return
    // a read only check on page open: get#UserDrives would make the personal drive
    const own = ec.entity.find('moqui.resource.ResourceDrive').condition('ownerUserId', ec.user.userId)
            .condition('driveKindEnumId', 'RdkPersonal').orderBy('driveId').limit(1).list()
    if (!own.length || own[0].archivedDate == null) { hasDrive = true; return }
    includeRecent = false
}
const drives = ec.service.sync().name('org.moqui.resource.FileServices.get#UserDrives').parameter('includeUsage', false).call()
if (ec.message.hasError()) return
driveList = Array.from(drives.driveList || []).map((drive) => ({driveId: drive.driveId,
    driveName: drive.isPersonal ? ec.l10n.localize('My files') : drive.driveName, isPersonal: drive.isPersonal === true,
    isRecords: drive.driveKindEnumId === 'RdkRecords', canWrite: drive.canWrite === true}))
hasDrive = driveList.length > 0
// an archived personal drive is not one to open
if (drives.personalDriveId && driveList.some((drive) => drive.driveId === drives.personalDriveId)) personalDriveId = drives.personalDriveId
if (!hasDrive || !includeRecent) return
const recent = ec.service.sync().name('org.moqui.resource.FileServices.find#Recent').parameter('limit', recentLimit || 12).call()
if (ec.message.hasError()) return
recentList = Array.from(recent.resultList || []).map((row) => {
    const kind = ec.service.sync().name('org.moqui.comms.FilePickerServices.get#FileType').parameters({name: row.name, isDirectory: false}).call()
    const slash = String(row.path || '').lastIndexOf('/')
    return {driveId: row.driveId, driveName: row.driveName ?? null, path: row.path, folderPath: slash > 0 ? String(row.path).slice(0, slash) : '',
        name: row.name, isDirectory: false, size: row.size ?? null, modified: row.modified ?? null, fileType: kind.fileType, icon: kind.icon}
})

fileList = []
breadcrumbList = []
canWrite = false
const out = ec.service.sync().name('org.moqui.resource.FileServices.list#Folder').parameters({driveId: driveId, path: path || ''}).call()
if (ec.message.hasError()) return
canWrite = !!(out.folder && (out.folder.canWrite || out.folder.canUpload))
breadcrumbList = Array.from(out.breadcrumbList || []).map((crumb, index) => ({name: index === 0 && out.drive && out.drive.driveKindEnumId === 'RdkPersonal'
    ? ec.l10n.localize('My files') : crumb.name, path: crumb.path}))
fileList = Array.from(out.fileList || []).map((row) => {
    const kind = ec.service.sync().name('org.moqui.comms.FilePickerServices.get#FileType').parameters({name: row.name,
        isDirectory: row.isDirectory === true}).call()
    return {driveId: driveId, path: row.path, name: row.name, isDirectory: row.isDirectory === true, size: row.size ?? null,
        modified: row.modified ?? null, fileType: row.isDirectory ? 'folder' : (row.fileType || kind.fileType), icon: kind.icon}
})

fileList = []
const term = String(text || '').trim()
if (!term) return
const found = ec.service.sync().name('org.moqui.resource.FileServices.find#Resources').parameters({text: term, limit: limit || 50}).call()
if (ec.message.hasError()) return
fileList = Array.from(found.resultList || []).map((row) => {
    const isDirectory = row.isDirectory === true
    const kind = ec.service.sync().name('org.moqui.comms.FilePickerServices.get#FileType').parameters({name: row.name, isDirectory: isDirectory}).call()
    const slash = String(row.path || '').lastIndexOf('/')
    return {driveId: row.driveId, driveName: row.driveName ?? null, path: row.path,
        folderPath: slash > 0 ? String(row.path).slice(0, slash) : '', name: row.name, isDirectory: isDirectory, size: row.size ?? null,
        modified: row.modified ?? null, fileType: isDirectory ? 'folder' : (row.fileType || kind.fileType), icon: kind.icon}
})
